(async () => {
  if (typeof P256 === 'undefined' && typeof globalThis !== 'undefined') {
    /* recipe may have bound only globalThis */
  }
  const P = (typeof P256 !== 'undefined') ? P256 : (globalThis && globalThis.P256);
  if (!P) return JSON.stringify({ok: false, err: 'P256 did not install — preload recipe x-p256 apply_now?'});
  const kp = P.genKeyPair();
  const s = await P.sign(kp, 'x-reply selftest');
  const v = await P.verify(kp.Q, 'x-reply selftest', s.r, s.s);
  return JSON.stringify({ok: v, err: v ? null : 'P256 self-verify failed (add-2007-bl I=4H^2 regression?)'});
})()

(async () => {
  const fn = (typeof abxProbeBearer === 'function')
    ? abxProbeBearer
    : (typeof globalThis !== 'undefined' && typeof globalThis.abxProbeBearer === 'function')
      ? globalThis.abxProbeBearer
      : null;
  if (!fn) return JSON.stringify({ok: false, err: 'abxProbeBearer missing — preload recipe x-bearer apply_now?'});
  return await fn();
})()

(async () => {
  const fn = (typeof abxEnsureAuthCtx === 'function')
    ? abxEnsureAuthCtx
    : (typeof globalThis !== 'undefined' && typeof globalThis.abxEnsureAuthCtx === 'function')
      ? globalThis.abxEnsureAuthCtx
      : null;
  if (!fn) return JSON.stringify({ok: false, err: 'abxEnsureAuthCtx missing — preload recipe x-auth-ctx apply_now?'});
  return await fn();
})()

// x-reply step: post tweet/root with full write-header set (txid + session-signature trio)
// helpers from recipe x-auth-ctx (abxB64keep / abxDerEncode / abxAuthHeaders / abxTxidGen)

(async () => {
  const ARGS = {{args_json}};
  const b64keep = (typeof abxB64keep === 'function') ? abxB64keep : globalThis.abxB64keep;
  const derEncode = (typeof abxDerEncode === 'function') ? abxDerEncode : globalThis.abxDerEncode;
  const authHeaders = (typeof abxAuthHeaders === 'function') ? abxAuthHeaders : globalThis.abxAuthHeaders;
  const txidGen = (typeof abxTxidGen === 'function') ? abxTxidGen : globalThis.abxTxidGen;
  if (!b64keep || !derEncode || !authHeaders || !txidGen) {
    return JSON.stringify({ok: false, err: 'x-auth-ctx helpers missing — preload recipe x-auth-ctx apply_now?'});
  }
  try {
    if (typeof P256 === 'undefined') return JSON.stringify({ok: false, err: 'P256 missing - run p256 step first'});
    const ctx = JSON.parse(localStorage.getItem('abx_txid_ctx') || 'null');
    const bindState = JSON.parse(localStorage.getItem('abx_bind') || 'null');
    if (!ctx || !ctx.animationKey) return JSON.stringify({ok: false, err: 'no txid ctx/animationKey - run ctx+bind step first'});
    if (!bindState || Number(bindState.expiresAt) < Date.now() + 60e3) return JSON.stringify({ok: false, err: 'binding stale - rerun ctx+bind step'});
    const key2 = {d: BigInt('0x' + bindState.d), Q: {x: BigInt('0x' + bindState.Qx), y: BigInt('0x' + bindState.Qy)}};
    const signHeaders = async (method, pathWithQuery) => {
      const ts = String(Math.floor(Date.now()));
      const sig = await P256.sign(key2, method + '|' + pathWithQuery + '|' + ts);
      return {
        'x-twitter-session-signature': b64keep(derEncode(sig.r, sig.s)),
        'x-twitter-session-timestamp': ts,
        'x-twitter-session-tokenhash': bindState.tokenhash
      };
    };
    const features = JSON.parse(localStorage.getItem('abx_ct_features'));
    const path = '/i/api/graphql/CUWCG7oBfrG71ZUXUtpwbw/CreateTweet';
    const trio = await signHeaders('POST', path);
    const txid = await txidGen('POST', path, ctx, ctx.animationKey);
    const variables = {
      tweet_text: ARGS.text,
      media: {media_entities: [], possibly_sensitive: false},
      dark_request: false
    };
    if (ARGS.reply_to) variables.reply = {in_reply_to_tweet_id: String(ARGS.reply_to), exclude_reply_user_ids: []};
    const r = await fetch(path, {
      method: 'POST', credentials: 'include',
      headers: {...authHeaders(), 'x-client-transaction-id': txid, ...trio},
      body: JSON.stringify({variables, features, queryId: 'CUWCG7oBfrG71ZUXUtpwbw'})
    });
    const t = await r.text();
    let j = null; try { j = JSON.parse(t); } catch {}
    const node = j && j.data && j.data.create_tweet && j.data.create_tweet.tweet_results && j.data.create_tweet.tweet_results.result;
    const core = node && node.__typename === 'TweetWithVisibilityResults' ? node.tweet : node;
    const err = j && j.errors && j.errors[0];
    return JSON.stringify({
      ok: !!core,
      status: r.status,
      tweet_id: core && core.legacy ? core.legacy.id_str : null,
      text_head: core && core.legacy ? core.legacy.full_text.slice(0, 60) : null,
      err_code: err ? err.code : null,
      err_msg: err ? err.message : null,
      body_head: core ? null : t.slice(0, 120)
    });
  } catch (e) {
    return JSON.stringify({ok: false, err: e.name + ': ' + e.message});
  }
})()

// x-reply step: verify the reply landed — TweetDetail focal=parent, our uid in thread
(async () => {
  const ARGS = {{args_json}};
  try {
    if (!ARGS.reply_to) return JSON.stringify({ok: true, skipped: true, why: 'root tweet - nothing to verify'});
    await new Promise(res => setTimeout(res, 1500));
    let uid = localStorage.getItem('abx_uid');
    const argUid = '{{uid}}';
    if (!uid && argUid) { uid = argUid; localStorage.setItem('abx_uid', uid); }
    const bearer = localStorage.getItem('abx_bearer');
    const ct0 = (document.cookie.match(/(?:^|;\s*)ct0=([^;]+)/) || [])[1];
    const features = JSON.parse(localStorage.getItem('abx_ct_features'));
    if (!bearer || !ct0 || !features) return JSON.stringify({ok: false, err: 'missing bearer/ct0/features'});
    const variables = {focalTweetId: String(ARGS.reply_to), withRuxInjections: false, includePromotedContent: true,
      withCommunityNoteHydrationEnabled: false, withBirdwatchNotes: false, withVoice: true,
      withSuperFollowsUserFields: false, withDownvotePerspective: false, withReactionsMetadata: false,
      withReactionsPerspective: false, withSuperFollowsTweetFields: false, withBirdwatchPivots: false};
    const q = '/i/api/graphql/FyR-GrebyjdkRoW1z6uCgQ/TweetDetail?variables=' +
      encodeURIComponent(JSON.stringify(variables)) + '&features=' + encodeURIComponent(JSON.stringify(features));
    const r = await fetch(q, {credentials: 'include', headers: {
      'authorization': 'Bearer ' + bearer,
      'x-twitter-auth-type': 'OAuth2Session',
      'x-csrf-token': ct0,
      'x-twitter-client-language': 'en',
      'x-twitter-active-user': 'yes'
    }});
    const t = await r.text();
    let j = null; try { j = JSON.parse(t); } catch {}
    if (!r.ok) return JSON.stringify({ok: false, verified: false, status: r.status, err_head: t.slice(0, 120)});
    const mine = [];
    const pick = (ic) => {
      const res = ic && ic.tweet_results && ic.tweet_results.result;
      const core = res && res.__typename === 'TweetWithVisibilityResults' ? res.tweet : res;
      const u = core && core.core && core.core.user_results && core.core.user_results.result;
      if (uid && u && u.rest_id === uid && core.legacy) mine.push(core.legacy.id_str);
    };
    const walk = (entries) => {
      for (const e of (entries || [])) {
        const c = e && e.content;
        if (!c) continue;
        if (c.itemContent) pick(c.itemContent);
        if (c.items) for (const it of c.items) pick(it.item && it.item.itemContent);
      }
    };
    for (const ins of ((j.data && j.data.threaded_conversation_with_injections_v2 && j.data.threaded_conversation_with_injections_v2.instructions) || [])) walk(ins.entries);
    return JSON.stringify({ok: true, verified: mine.length > 0, mine_in_thread: mine});
  } catch (e) {
    return JSON.stringify({ok: false, verified: false, err: e.name + ': ' + e.message});
  }
})()
